use std::env;
use std::fs;
use std::io;
use std::path::Path;

fn main() -> Result<(), io::Error> {
    if let Some(out_dir) = env::var_os("OUT_DIR") {
        fs::write(
            Path::new(&out_dir).join("generated.rs"),
            "// generated by the build script\npub struct Generated;\n",
        )?;
    }

    Ok(())
}
